SELECT Customers.DESCRIPITIVE_ATTRIBUTE_2, Discount.DESCRIPITIVE_ATTRIBUTE_6 FROM Renting_history JOIN Customers ON Renting_history.customer_id = Customers.id JOIN Discount ON Renting_history.discount_id = Discount.id WHERE (Renting_history.customer_id, Renting_history.discount_id) IN ( SELECT customer_id, discount_id FROM Renting_history GROUP BY customer_id, discount_id ORDER BY COUNT(*) DESC LIMIT 1 )
SELECT Discount.DESCRIPITIVE_ATTRIBUTE_6, COUNT(*) AS count FROM Renting_history JOIN Discount ON Renting_history.discount_id = Discount.id JOIN Customers ON Renting_history.customer_id = Customers.id WHERE Customers.DESCRIPITIVE_ATTRIBUTE_2 = 'Discount' GROUP BY Discount.DESCRIPITIVE_ATTRIBUTE_6 ORDER BY count DESC LIMIT 1
SELECT Discount.DESCRIPITIVE_ATTRIBUTE_6 FROM Discount JOIN Renting_history ON Renting_history.discount_id = Discount.id JOIN Customers ON Customers.id = Renting_history.customer_id GROUP BY Discount.DESCRIPITIVE_ATTRIBUTE_6 ORDER BY COUNT(Customers.id) DESC LIMIT 1
SELECT Students.student_id, Students.bio_data, Students.student_details FROM Students JOIN ( SELECT student_id, COUNT(*) as class_count FROM Transcripts GROUP BY student_id HAVING COUNT(*) >= 2 ) AS T2_COUNT ON Students.student_id = T2_COUNT.student_id JOIN ( SELECT student_id, COUNT(*) as detention_count FROM Students_Addresses GROUP BY student_id HAVING COUNT(*) < 2 ) AS T9_COUNT ON Students.student_id = T9_COUNT.student_id
SELECT Students.student_id, Achievements.achievement_details, Achievements.other_details FROM Students JOIN Achievements ON Students.student_id = Achievements.student_id WHERE Students.student_id IN ( SELECT Students.student_id FROM Students JOIN Achievements ON Students.student_id = Achievements.student_id GROUP BY Students.student_id HAVING COUNT(Achievements.achievement_id) >= 2 ) OR Students.student_id IN ( SELECT Students.student_id FROM Students JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id GROUP BY Students.student_id HAVING COUNT(Students_Addresses.student_address_id) < 2 )
SELECT Students.student_id, Classes.DESCRIBITIVE_ATTRIBUTE_9, Detention.other_details, Achievements.achievement_details FROM Students JOIN Classes ON Students.student_id = Classes.student_id JOIN Detention ON Students.student_id = Detention.student_id JOIN Achievements ON Students.student_id = Achievements.student_id WHERE Classes.DESCRIBITIVE_ATTRIBUTE_9 LIKE '%data%' AND Classes.DESCRIBITIVE_ATTRIBUTE_9 NOT LIKE 'net%' AND Detention.other_details NOT LIKE 'net%' AND Achievements.achievement_details NOT LIKE 'net%'
SELECT Students.bio_data, Students.student_details FROM Students JOIN Classes ON Students.student_id = Classes.student_id JOIN Teachers ON Classes.teacher_id = Teachers.teacher_id WHERE Teachers.teacher_details LIKE '%data%' AND Teachers.teacher_details NOT LIKE 'net%'
SELECT Students.student_id, SUM(Student_Loans.amount_of_loan) AS loan_amount, Student_Loans.date_of_loan AS loan_date FROM Student_Loans JOIN Students ON Student_Loans.student_id = Students.student_id JOIN Achievements ON Achievements.student_id = Students.student_id WHERE Achievements.achievement_id IN ( SELECT achievement_id FROM Achievements GROUP BY achievement_id HAVING COUNT(achievement_id) >= 2 ) GROUP BY Students.student_id, Student_Loans.date_of_loan
SELECT Student_Loans.amount_of_loan, Student_Loans.date_of_loan FROM Student_Loans JOIN Students ON Student_Loans.student_id = Students.student_id JOIN ( SELECT student_id, COUNT(*) as count FROM Transcripts GROUP BY student_id HAVING COUNT(*) >= 2 ) AS T2_COUNT ON Students.student_id = T2_COUNT.student_id
SELECT Students.student_id, COUNT(Transcripts.transcript_id) + COUNT(Behaviour_Monitoring.behaviour_monitoring_id) + COUNT(Student_Events.event_id) + COUNT(Student_Loans.student_loan_id) + COUNT(Classes.class_id) + COUNT(Students_Addresses.student_address_id) + COUNT(Detention.detention_id) + COUNT(Achievements.achievement_id) AS detail FROM Students LEFT JOIN Transcripts ON Students.student_id = Transcripts.student_id LEFT JOIN Behaviour_Monitoring ON Students.student_id = Behaviour_Monitoring.student_id LEFT JOIN Student_Events ON Students.student_id = Student_Events.student_id LEFT JOIN Student_Loans ON Students.student_id = Student_Loans.student_id LEFT JOIN Classes ON Students.student_id = Classes.student_id LEFT JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id LEFT JOIN Detention ON Students.student_id = Detention.student_id LEFT JOIN Achievements ON Students.student_id = Achievements.student_id GROUP BY Students.student_id ORDER BY COUNT(Transcripts.transcript_id) + COUNT(Behaviour_Monitoring.behaviour_monitoring_id) + COUNT(Student_Events.event_id) + COUNT(Student_Loans.student_loan_id) + COUNT(Classes.class_id) + COUNT(Students_Addresses.student_address_id) + COUNT(Detention.detention_id) + COUNT(Achievements.achievement_id) DESC
SELECT Students.bio_data, Students.student_id FROM Students JOIN Achievements ON Students.student_id = Achievements.student_id GROUP BY Students.student_id ORDER BY COUNT(Achievements.achievement_id) DESC LIMIT 1
SELECT Students.* FROM Students JOIN ( SELECT Transcripts.student_id FROM Transcripts GROUP BY Transcripts.student_id HAVING COUNT(Transcripts.student_id) = ( SELECT MAX(COUNT(Transcripts.student_id)) FROM Transcripts GROUP BY Transcripts.student_id ) ) AS Transcripts ON Students.student_id = Transcripts.student_id JOIN ( SELECT Transcripts.student_id FROM Transcripts GROUP BY Transcripts.student_id HAVING COUNT(Transcripts.student_id) = 3 ) AS Behaviour_Monitoring ON Students.student_id = Behaviour_Monitoring.student_id
SELECT Students.student_id, Students.bio_data, Students.student_details, Transcripts.date_of_transcript, Transcripts.transcript_details, Student_Events.event_date, Student_Events.other_details, Student_Loans.date_of_loan, Student_Loans.amount_of_loan, Student_Loans.other_details FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Student_Events ON Students.student_id = Student_Events.student_id JOIN Student_Loans ON Students.student_id = Student_Loans.student_id WHERE Transcripts.date_of_transcript IN ( SELECT date_of_transcript FROM Transcripts GROUP BY date_of_transcript HAVING COUNT(date_of_transcript) = 3 ) AND Student_Loans.amount_of_loan IN ( SELECT amount_of_loan FROM Student_Loans GROUP BY amount_of_loan HAVING COUNT(amount_of_loan) = ( SELECT COUNT(amount_of_loan) FROM Student_Loans GROUP BY amount_of_loan ORDER BY COUNT(amount_of_loan) DESC LIMIT 1 ) )
SELECT Students.student_id, Students.bio_data, Students.student_details FROM Students JOIN ( SELECT student_id, COUNT(*) as count FROM Transcripts GROUP BY student_id HAVING COUNT(*) = ( SELECT MAX(count) FROM ( SELECT student_id, COUNT(*) as count FROM Transcripts GROUP BY student_id ) ) ) AS T2_SUBQUERY ON Students.student_id = T2_SUBQUERY.student_id UNION SELECT Students.student_id, Students.bio_data, Students.student_details FROM Students JOIN ( SELECT student_id, COUNT(*) as count FROM Behaviour_Monitoring GROUP BY student_id HAVING COUNT(*) = ( SELECT MAX(count) FROM ( SELECT student_id, COUNT(*) as count FROM Behaviour_Monitoring GROUP BY student_id ) ) ) AS T3_SUBQUERY ON Students.student_id = T3_SUBQUERY.student_id UNION SELECT Students.student_id, Students.bio_data, Students.student_details FROM Students JOIN ( SELECT student_id, COUNT(*) as count FROM Student_Events GROUP BY student_id HAVING COUNT(*) = ( SELECT MAX(count) FROM ( SELECT student_id, COUNT(*) as count FROM Student_Events GROUP BY student_id ) ) ) AS T4_SUBQUERY ON Students.student_id = T4_SUBQUERY.student_id UNION SELECT Students.student_id, Students.bio_data, Students.student_details FROM Students JOIN ( SELECT student_id, COUNT(*) as count FROM Student_Loans GROUP BY student_id HAVING COUNT(*) = ( SELECT MAX(count) FROM ( SELECT student_id, COUNT(*) as count FROM Student_Loans GROUP BY student_id ) ) ) AS T6_SUBQUERY
SELECT Students.bio_data, Students.student_details FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Behaviour_Monitoring ON Students.student_id = Behaviour_Monitoring.student_id JOIN Student_Events ON Students.student_id = Student_Events.student_id JOIN Student_Loans ON Students.student_id = Student_Loans.student_id JOIN Detention ON Students.student_id = Detention.student_id JOIN Achievements ON Students.student_id = Achievements.student_id GROUP BY Students.student_id ORDER BY COUNT(Students.student_id) DESC LIMIT 1
SELECT Ref_Event_Types.DESCRIPITIVE_ATTRIBUTE_8 AS event_type, COUNT(Students.student_id) AS number_of_students FROM Behaviour_Monitoring JOIN Students ON Behaviour_Monitoring.student_id = Students.student_id JOIN Ref_Event_Types ON Behaviour_Monitoring.behaviour_monitoring_details = Ref_Event_Types.event_type_code GROUP BY Ref_Event_Types.DESCRIPITIVE_ATTRIBUTE_8 HAVING COUNT(Students.student_id) = (SELECT MAX(number_of_students) FROM (SELECT Ref_Event_Types.DESCRIPITIVE_ATTRIBUTE_8, COUNT(Students.student_id) AS number_of_students FROM Behaviour_Monitoring JOIN Students ON Behaviour_Monitoring.student_id = Students.student_id JOIN Ref_Event_Types ON Behaviour_Monitoring.behaviour_monitoring_details = Ref_Event_Types.event_type_code GROUP BY Ref_Event_Types.DESCRIPITIVE_ATTRIBUTE_8))
SELECT Ref_Event_Types.event_type_description AS event_type_description, Ref_Event_Types.event_type_code AS event_type_code, COUNT(Transcripts.transcript_id) + COUNT(Behaviour_Monitoring.behaviour_monitoring_id) + COUNT(Student_Events.event_id) + COUNT(Student_Loans.student_loan_id) + COUNT(Students_Addresses.student_address_id) + COUNT(Detention.detention_id) + COUNT(Achievements.achievement_id) AS num_students FROM Students LEFT JOIN Transcripts ON Students.student_id = Transcripts.student_id LEFT JOIN Behaviour_Monitoring ON Students.student_id = Behaviour_Monitoring.student_id LEFT JOIN Student_Events ON Students.student_id = Student_Events.student_id LEFT JOIN Ref_Event_Types ON Students.student_id = Ref_Event_Types.event_type_code LEFT JOIN Student_Loans ON Students.student_id = Student_Loans.student_id LEFT JOIN Classes ON Students.student_id = Classes.student_id LEFT JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id LEFT JOIN Detention ON Students.student_id = Detention.student_id LEFT JOIN Achievements ON Students.student_id = Achievements.student_id
SELECT COUNT(DISTINCT Students.student_id) FROM Students JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id WHERE Students.student_id NOT IN ( SELECT Student_Loans.student_id FROM Student_Loans WHERE Student_Loans.amount_of_loan > 0 )
SELECT COUNT(Students.student_id) FROM Students LEFT JOIN Student_Loans ON Students.student_id = Student_Loans.student_id LEFT JOIN Achievements ON Students.student_id = Achievements.student_id WHERE Achievements.achievement_type_code IS NULL
SELECT Ref_Event_Types.event_type_description AS TYPE_CODE, Ref_Event_Types.event_type_description AS DESCRIPTION FROM Ref_Event_Types LEFT JOIN Ref_Achievement_Type ON Ref_Event_Types.event_type_code = Ref_Achievement_Type.achievement_type_code LEFT JOIN Ref_Address_Types ON Ref_Event_Types.event_type_code = Ref_Address_Types.address_type_code LEFT JOIN Ref_Detention_Type ON Ref_Event_Types.event_type_code = Ref_Detention_Type.detention_type_code GROUP BY Ref_Event_Types.event_type_description ORDER BY COUNT(Ref_Event_Types.event_type_description) ASC LIMIT 1
SELECT event_type_description, COUNT(*) AS frequency FROM Ref_Event_Types GROUP BY event_type_description ORDER BY frequency ASC LIMIT 1
SELECT Students.student_id, Students.bio_data, Students.student_details, Transcripts.date_of_transcript, Transcripts.transcript_details, Student_Loans.amount_of_loan FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Student_Loans ON Students.student_id = Student_Loans.student_id WHERE Student_Loans.amount_of_loan > (SELECT AVG(amount_of_loan) FROM Student_Loans) ORDER BY Student_Loans.amount_of_loan DESC
SELECT Students.bio_data, Students.student_details, Student_Loans.amount_of_loan FROM Students JOIN Student_Loans ON Students.student_id = Student_Loans.student_id WHERE Student_Loans.amount_of_loan > (SELECT AVG(amount_of_loan) FROM Student_Loans)
SELECT Students.bio_data, Students.student_details FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id WHERE Transcripts.date_of_transcript = (SELECT MIN(date_of_transcript) FROM Transcripts)
SELECT Students.student_id, Students.bio_data, Students.student_details, Student_Events.event_id, Student_Events.other_details FROM Students JOIN Student_Events ON Students.student_id = Student_Events.student_id JOIN Transcripts ON Students.student_id = Transcripts.student_id WHERE Transcripts.date_of_transcript = (SELECT MIN(date_of_transcript) FROM Transcripts)
SELECT Ref_Achievement_Type.achievement_type_description, COUNT(Achievements.achievement_id) AS count FROM Ref_Achievement_Type JOIN Achievements ON Ref_Achievement_Type.achievement_type_code = Achievements.achievement_type_code GROUP BY Ref_Achievement_Type.achievement_type_description ORDER BY count DESC LIMIT 1
SELECT Ref_Achievement_Type.DESCRIBITIVE_ATTRIBUTE_7, COUNT(Students.student_id) as count FROM Students JOIN Ref_Achievement_Type ON Students.student_id = Ref_Achievement_Type.achievement_type_code WHERE Ref_Achievement_Type.achievement_type_code IS NOT NULL GROUP BY Ref_Achievement_Type.DESCRIBITIVE_ATTRIBUTE_7 ORDER BY count DESC
